INSERT INTO main_app_briefing VALUES(70,'stocks','2026-09-14 20:21:16.869684','US stocks steady despite rising interest rates and geopolitical tensions',replace('```json\n{"headline": "US stocks steady despite rising interest rates and geopolitical tensions",\n "quiet": false,\n "items": [\n  {"text": "Despite rising U.S. interest rates and geopolitical tensions with Iran, the stock market remains largely unaffected, supported by robust corporate profits, especially in AI sectors.", "url": "https://www.axios.com/2026/09/14/ai-stocks-interest-rates"},\n  {"text": "AI stocks declined following calls for a slowdown in AI development due to safety concerns, with companies like Nvidia and Softbank seeing notable decreases.", "url": "https://apnews.com/article/0b44bfb43960c6ae850567c0c4e5003a"},\n  {"text": "U.S. stocks declined as Treasury yields soared due to rising inflationary pressures and surging oil prices, with the 2-year and 10-year Treasury yields reaching their highest levels since mid-2024 and 2023, respectively.", "url": "https://www.kiplinger.com/investing/stocks/stocks-drop-as-treasury-yields-hit-new-highs-stock-market-today"},\n  {"text": "Retail investors showed diminished bullishness towards the stock market, reflected in a 3.9% decline in Charles Schwab’s Trading Activity Index (STAX), signaling growing investor caution.", "url": "https://www.axios.com/2026/09/08/schwab-retail-investors-august"},\n  {"text": "U.S. home sales declined to their slowest annual pace in over a year, with existing home sales falling 2% from July to an annual rate of 3.98 million units, indicating a slowdown in the housing market.", "url": "https://apnews.com/article/f6805f57c7e0f147592357f8e378030d"}\n ]}\n``` ','\n',char(10)),'[{"text": "Despite rising U.S. interest rates and geopolitical tensions with Iran, the stock market remains largely unaffected, supported by robust corporate profits, especially in AI sectors.", "url": "https://www.axios.com/2026/09/14/ai-stocks-interest-rates"}, {"text": "AI stocks declined following calls for a slowdown in AI development due to safety concerns, with companies like Nvidia and Softbank seeing notable decreases.", "url": "https://apnews.com/article/0b44bfb43960c6ae850567c0c4e5003a"}, {"text": "U.S. stocks declined as Treasury yields soared due to rising inflationary pressures and surging oil prices, with the 2-year and 10-year Treasury yields reaching their highest levels since mid-2024 and 2023, respectively.", "url": "https://www.kiplinger.com/investing/stocks/stocks-drop-as-treasury-yields-hit-new-highs-stock-market-today"}, {"text": "Retail investors showed diminished bullishness towards the stock market, reflected in a 3.9% decline in Charles Schwab\u2019s Trading Activity Index (STAX), signaling growing investor caution.", "url": "https://www.axios.com/2026/09/08/schwab-retail-investors-august"}, {"text": "U.S. home sales declined to their slowest annual pace in over a year, with existing home sales falling 2% from July to an annual rate of 3.98 million units, indicating a slowdown in the housing market.", "url": "https://apnews.com/article/f6805f57c7e0f147592357f8e378030d"}]',0,'gpt-4o-mini',0.011470000000000000195,'');
INSERT INTO main_app_briefing VALUES(71,'crypto','2026-09-14 20:21:20.856505','Bitcoin ETF outflows continue; Ether ETFs see inflows amid market shifts',replace('```json\n{\n  "headline": "Bitcoin ETF outflows continue; Ether ETFs see inflows amid market shifts",\n  "quiet": false,\n  "items": [\n    {\n      "text": "Bitcoin ETFs experienced $462.73 million in net outflows last week, ending a three-week inflow streak, while Ether ETFs attracted $197 million in inflows, extending their winning run to four weeks.",\n      "url": "https://news.bitcoin.com/bitcoin-etf/ether-xrp-and-solana-record-weekly-gains-as-bitcoin-etfs-lose-463m/"\n    },\n    {\n      "text": "Hackers drained approximately $320 million in Bitcoin from the Liquid Network, emptying about 95% of its federation wallet; attackers claim to be ''white-hat'' and will return funds after vulnerability is fixed.",\n      "url": "https://www.tomshardware.com/tech-industry/cryptocurrency/hackers-drain-usd320-million-in-bitcoin-from-liquid-network-emptying-roughly-95-percent-of-federation-wallet-attackers-claim-theyre-the-good-guys-and-will-return-funds-after-the-vulnerability-is-fixed"\n    }\n  ]\n}\n``` ','\n',char(10)),'[{"text": "Bitcoin ETFs experienced $462.73 million in net outflows last week, ending a three-week inflow streak, while Ether ETFs attracted $197 million in inflows, extending their winning run to four weeks.", "url": "https://news.bitcoin.com/bitcoin-etf/ether-xrp-and-solana-record-weekly-gains-as-bitcoin-etfs-lose-463m/"}, {"text": "Hackers drained approximately $320 million in Bitcoin from the Liquid Network, emptying about 95% of its federation wallet; attackers claim to be ''white-hat'' and will return funds after vulnerability is fixed.", "url": "https://www.tomshardware.com/tech-industry/cryptocurrency/hackers-drain-usd320-million-in-bitcoin-from-liquid-network-emptying-roughly-95-percent-of-federation-wallet-attackers-claim-theyre-the-good-guys-and-will-return-funds-after-the-vulner