INSERT INTO main_app_briefing VALUES(98,'stocks','2026-09-16 00:24:22.811521','US stocks decline amid rising oil prices and bond yields',replace('```json\n{\n  "headline": "US stocks decline amid rising oil prices and bond yields",\n  "quiet": false,\n  "items": [\n    {\n      "text": "US stock markets fell as oil prices surged and bond yields rose, with the S&P 500 dropping 0.4% and the Nasdaq composite declining 0.8%.",\n      "url": "https://apnews.com/article/123ddc2d8ba06c324cbbd899f7eeebd2"\n    },\n    {\n      "text": "The yield on the 10-year U.S. Treasury rose to 5.00%, its highest since 2023, driven by inflation concerns and government debt.",\n      "url": "https://apnews.com/article/123ddc2d8ba06c324cbbd899f7eeebd2"\n    },\n    {\n      "text": "Oil prices surged, with Brent crude rising 2.9% to $108.75 per barrel, amid doubts about the impact of ongoing conflict with Iran on oil transport through the Strait of Hormuz.",\n      "url": "https://apnews.com/article/123ddc2d8ba06c324cbbd899f7eeebd2"\n    },\n    {\n      "text": "Stocks reliant on consumer spending, such as Chipotle (down 5.9%) and Dollar Tree (down 5.4%), were hit hard due to rising oil prices and bond yields.",\n      "url": "https://apnews.com/article/123ddc2d8ba06c324cbbd899f7eeebd2"\n    },\n    {\n      "text": "AI stocks showed some recovery after a sharp drop, with Nvidia and AMD posting gains, indicating resilience in the sector despite broader market declines.",\n      "url": "https://apnews.com/article/123ddc2d8ba06c324cbbd899f7eeebd2"\n    }\n  ]\n}\n``` ','\n',char(10)),'[{"text": "US stock markets fell as oil prices surged and bond yields rose, with the S&P 500 dropping 0.4% and the Nasdaq composite declining 0.8%.", "url": "https://apnews.com/article/123ddc2d8ba06c324cbbd899f7eeebd2"}, {"text": "The yield on the 10-year U.S. Treasury rose to 5.00%, its highest since 2023, driven by inflation concerns and government debt.", "url": "https://apnews.com/article/123ddc2d8ba06c32