INSERT INTO main_app_briefing VALUES(118,'stocks','2026-09-16 20:26:21.796321','US stocks decline as Fed raises rates, yields surge, and oil prices climb',replace('```json\n{\n  "headline": "US stocks decline as Fed raises rates, yields surge, and oil prices climb",\n  "quiet": false,\n  "items": [\n    {\n      "text": "Federal Reserve raises benchmark interest rate by 0.25% to 3.75%-4.00%, first hike since mid-2023, aiming to combat persistent inflation. [Source](https://apnews.com/article/8d645bd4cbf32974e68c5bc4cfaa1f61)",\n      "url": "https://apnews.com/article/8d645bd4cbf32974e68c5bc4cfaa1f61"\n    },\n    {\n      "text": "10-year Treasury yield reaches 5.04%, highest since 2007, raising borrowing costs and pressuring stock valuations. [Source](https://www.axios.com/2026/09/16/rates-yields-stocks-ai)",\n      "url": "https://www.axios.com/2026/09/16/rates-yields-stocks-ai"\n    },\n    {\n      "text": "Oil prices surge 4.5% to $105.84 per barrel amid Middle East tensions, contributing to market volatility. [Source](https://apnews.com/article/123ddc2d8ba06c324cbbd899f7eeebd2)",\n      "url": "https://apnews.com/article/123ddc2d8ba06c324cbbd899f7eeebd2"\n    },\n    {\n      "text": "S&P 500 falls 0.4% to 7,551.81, Dow Jones drops 1.2% to 51,461.90, Nasdaq edges down 0.1% to 25,978.42, following Fed''s rate hike. [Source](https://apnews.com/article/b082e78c9b572b6b0a94b8033a0ee96b)",\n      "url": "https://apnews.com/article/b082e78c9b572b6b0a94b8033a0ee96b"\n    },\n    {\n      "text": "Investors express concern over rising bond yields and potential impact on stock market, with AI investments under scrutiny. [Source](https://www.axios.com/2026/09/16/bonds-yields-premium-stocks)",\n      "url": "https://www.axios.com/2026/09/16/bonds-yields-premium-stocks"\n    }\n  ]\n}\n``` ','\n',char(10)),'[{"text": "Federal Reserve raises benchmark interest rate by 0.25% to 3.75%-4.00%, first hike since mid-2023, aiming to combat persistent inflation. [Source](https://apnews.com/article/8d645bd4cbf32974e68c5bc4cfaa1f61)", "url": "https://apnews.com/article/8d645bd4cbf32974e68c5bc4cfaa1f61"}, {"text": "10-year Treasury yield reaches 5.04%, highest since 2007, raising borrowing costs and pressuring stock valuations. [Source](https://www.axios.com/2026/09/16/rates-yields-stocks-ai)", "url": "https://www.axios.com/2026/09/16/rates-yields-stocks-ai"}, {"text": "Oil prices surge 4.5% to $105.84 per barrel amid Middle East tensions, contributing to market volatility. [Source](https://apnews.com/article/123ddc2d8ba06c324cbbd899f7eeebd2)", "url": "https://apnews.com/article/123ddc2d8ba06c324cbbd899f7eeebd2"}, {"text": "S&P 500 falls 0.4% to 7,551.81, Dow Jones drops 1.2% to 51,461.90, Nasdaq edges down 0.1% to 25,978.42, following Fed''s rate hike. [Source](https://apnews.com/article/b082e78c9b572b6b0a94b8033a0ee96b)", "url": "https://apnews.com/article/b082e78c9b572b6b0a94b8033a0ee96b"}, {"text": "Investors express concern over rising bond yields and potential impact on stock market, with AI investments under scrutiny. [Source](https://www.axios.com/2026/09/16/bonds-yields-premium-stocks)", "url": "https://www.axios.com/2026/09/16/bonds-yields-premium-stocks"}]',0,'gpt-4o-mini',0.011566999999999998394,'');
